 		switch(iRet) {
 			case RS_RET_OK:
-				actionSetState(pThis, ACT_STATE_ITX);
+				actionSetState(pThis, pWti, ACT_STATE_ITX);
 				break;
 			case RS_RET_SUSPENDED:
-				actionRetry(pThis);
+				actionRetry(pThis, pWti);
 				break;
 			case RS_RET_DISABLE_ACTION:
-				actionDisable(pThis);
+				actionDisable(pThis, pWti);
 				break;
 			default:FINALIZE;
 		}
@@ -780,7 +781,7 @@ finalize_it:
